// Притчі — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Притчі Соломона, сина Давидового, царя Ізраїльського,","щоб пізнати мудрість і наставляння, зрозуміти слова розуму;","засвоїти правила розсудливости, правосуддя, суду і правоти;","простим дати розважливість, юнаку — знання і розсудливість;","послухає мудрий — і примножить пізнання, і розумний знайде мудрі поради;","щоб розуміти притчу і хитромудру мову, слова мудреців і загадки їхні.","Початок мудрости — страх Господній; [добре розуміння в усіх, кого воно водить; а благоговіння до Бога — початок розуміння;] нерозумні тільки нехтують мудрість і наставляння.","Слухай, сину мій, повчання батька твого і не відкидай заповіту матері твоєї,","тому що це — прекрасний вінок для голови твоєї і прикраса для шиї твоєї.","Сину мій! якщо будуть схиляти тебе грішники, не погоджуйся;","якщо будуть говорити: «йди з нами, зробимо засідку для убивства, підстережемо непорочного без вини,","живих проковтнемо їх, як пекло, і — цілих, як тих, що сходять у могилу;","наберемо всякого дорогоцінного майна, наповнимо доми наші здобич чю;","жереб твій ти будеш кидати разом з нами, склад один буде в усіх нас», —","сину мій! не ходи в путь з ними, утримай ногу твою від путі їх,","тому що ноги їхні біжать до зла і поспішають на пролиття крови.","У очах усіх птахів даремно розставляються тенета,","а роблять за сідку для їхньої крови і підстерігають їхні душі.","Такі путі кожного, хто жадає чужого добра: воно віднімає життя у того, хто заволодів ним.","Премудрість виголошує на вулиці, на площах підносить голос свій,","у головних місцях зібрань проповідує, біля входів у міські ворота говорить промову свою:","«доки, невігласи, будете любити неуцтво? доки буйні будуть тішитися буйством? доки нерозумні будуть ненавидіти знання?","Зверніться до мого викривання: ось, я виллю на вас дух мій, сповіщу вам слова мої.","Я кликала, і ви не послухалися; простягала руку мою, і не було того, хто слухає;","і ви відкинули всі мої поради, і викривань моїх не прийняли.","За те і я посміюся з вашої загибелі; порадію, коли прийде на вас жах;","коли прийде на вас жах, як буря, і лихо, як вихор, принесеться на вас; коли осягнуть вас скорбота і тиснява.","Тоді будуть кликати мене, і я не почую; зранку будуть шукати мене, і не знайдуть мене.","За те, що вони зненавиділи знання і не обрали для себе страху Господнього,","не прийняли поради моєї, знехтували усі викривання мої;","за те і будуть вони споживати від плодів шляхів своїх і насичуватися від помислів їх.","Тому що впертість невігласів уб’є їх, і безтурботність нерозумних погубить їх,","а той, хто слухає мене, буде жити безпечно і спокійно, не боячись зла»."],"x":{"1":"10.4.32","5":"30.10.28","7":"24.28.28|27.12.13|30.1.15","9":"26.4.9|30.6.32","10":"26.4.14","11":"32.5.26|43.7.2","12":"25.123.3","15":"25.1.1","16":"31.59.7|62.3.15","18":"50.26.16","20":"26.8.1-2|52.11.49","21":"26.8.3","24":"31.65.12|31.66.4|32.7.13","26":"4.28.63|36.21.17","28":"31.1.15|32.11.11","29":"26.1.24|54.13.40","31":"31.3.10","33":"25.111.7"}},{"v":["Сину мій! якщо ти приймеш слова мої і збережеш при собі заповіді мої,","так що вухо твоє зробиш уважним до мудрости і нахилиш серце твоє до роздумування;","якщо будеш закликати знання і звертатися до розуму;","якщо будеш шукати його, як срібла, і відшукувати його, як скарб,","то зрозумієш страх Господній і знайдеш пізнання про Бога.","Тому що Господь дає мудрість; з уст Його — знання і розум;","Він зберігає для праведних спасіння; Він — щит для тих, хто ходить непорочно;","Він охороняє путі правди й оберігає стежки святих Своїх.","Тоді ти зрозумієш правду і правосуддя і прямоту, усякий добрий шлях.","Коли мудрість увійде в серце твоє, і знання буде приємне душі твоїй,","тоді розсудливість буде оберігати тебе, розум буде охороняти тебе,","щоб спасти тебе від шляху злого, від людини, яка говорить неправду,","від тих, які залишають путі прямі, щоб ходити шляхами темряви;","від тих, які радіють, чинячи зло, захоплюються злою розпустою,","шляхи яких криві, і які блукають на стежках своїх;","щоб спасти тебе від дружини іншого, від чужої, яка промовляє солодкі слова свої,","яка залишила керівника юности своєї і забула завіт Бога свого.","Дім її веде до смерти, і шляхи її — до мерців;","ніхто з тих, що ввійшли до неї, не повертається і не вступає на путь життя.","Тому ходи шляхом добрих і тримайся стежок праведників,","бо праведні будуть жити на землі, і непорочні будуть перебувати на ній;","а беззаконні будуть знищені з землі, і віроломні викорінені з неї."],"x":{"2":"52.8.18","4":"50.13.44-46","6":"10.3.9:12|24.32.8|29.7.15|68.2.3","7":"25.83.12","13":"24.23.14|53.3.19","21":"25.36.9|50.5.5","22":"24.18.17"}},{"v":["Сину мій! повчання мого не забувай, і заповіді мої нехай зберігає серце твоє;","бо довготи днів, літ життя і миру вони додадуть тобі.","Милість і істина нехай не залишають тебе: обв’яжи ними шию твою, напиши їх на скрижалі серця твого,","і знайдеш милість і благовоління в очах Бога і людей.","Уповай на Господа всім серцем твоїм, і не покладайся на розум твій.","У всіх путях твоїх пізнавай Його, і Він направить стежки твої.","Не будь мудрецем в очах твоїх; бійся Господа і віддаляйся від зла:","це буде здоров’ям для тіла твого і споживою для кісток твоїх.","Шануй Господа від майна твого і від початків усіх прибутків твоїх,","і наповняться скарбниці твої до надлишку, і точила твої будуть переливатися новим вином.","Покарання Господнього, сину мій, не відкидай, і не тяготися викриванням Його;","бо кого любить Господь, того карає і благоволить до того, як батько до сина свого.","Блаженний муж, який здобув мудрість, і людина, яка придбала розум, —","тому що надбання її краще за придбання срібла, і прибутку від неї більше, ніж від золота:","вона дорожче за дорогоцінне каміння; [ніяке зло не може противитися їй; вона добре відома всім, хто наближається до неї,] і ніщо з бажаного тобою не зрівняється з нею.","Довголіття — у правиці її, а в лівій (руці) у неї — багатство і слава; [з уст її виходить правда; закон і милість вона на язиці носить;]","путі її — путі приємні, і всі стежки її — мирні.","Вона — древо життя для тих, які здобувають її, — і блаженні, які зберігають її!","Господь премудрістю заснував землю, небеса утвердив розумом;","Його премудрістю розкрилися безодні, і хмари кроплять росою.","Сину мій! не випускай їх з очей твоїх; зберігай розсудливість і розважливість,","і вони будуть життям для душі твоєї і прикрасою для шиї твоєї.","Тоді безпечно підеш шляхом твоїм, і нога твоя не спіткнеться.","Коли ляжеш спати, — не будеш боятися; і коли заснеш, — сон твій приємним буде.","Не убоїшся несподіваного страху і пагуби від нечестивих, коли вона прийде;","тому що Господь буде упованням твоїм і збереже ногу твою від уловлення.","Не відмовляй у благодіянні нужденному, коли рука твоя в силі зробити його.","Не говори другові твоєму: «піди і прийди знову, і завтра я дам», коли ти маєш при собі. [Тому що ти не знаєш, що принесе прийдешній день.]","Не замишляй проти ближнього твого зла, коли він без побоювання живе з тобою.","Не сварися з людиною без причини, коли вона не зробила зла тобі.","Не змагайся з людиною, яка чинить насилля, і не обирай жодного зі шляхів її;","тому що мерзота перед Господом розпусний, а з праведними у Нього спілкування.","Прокляття Господнє на домі нечестивого, а житло благочестивих Він благословляє.","Якщо з кощунників Він насміхається, то смиренним дає благодать.","Мудрі успадковують славу, а нерозумні — ганьбу."],"x":{"2":"4.8.1|4.30.16","4":"62.12.17","5":"32.9.23|11.18.5","7":"62.12.16|27.7.17","9":"18.4.7|30.4.1|52.14.13","11":"24.5.17|75.12.5|76.3.19","14":"24.28.15|26.8.11","16":"26.4.10|26.9.11","18":"26.11.30|26.15.4","19":"25.32.6","23":"25.36.24","24":"25.3.6|25.4.9","25":"25.111.7","27":"30.4.2","28":"56.4.10|64.8.12","31":"25.36.1|25.72.3","33":"4.28.15|49.2.2","34":"55.4.6|56.5.5"}},{"v":["Слухайте, діти, настановлення батька, і пильнуйте, щоб навчитися розуму,","тому що я дав вам добре вчення. Не залишайте заповіді моєї.","Бо і я був син у батька мого, і єдиний у матері моєї, яка ніжно любила мене,","і він учив мене і говорив мені: нехай утримає серце твоє слова мої; зберігай заповіді мої, і живи.","Здобувай мудрість, здобувай розум; не забувай цього і не відхиляйся від слів вуст моїх.","Не залишай її, і вона буде охороняти тебе; люби її, і вона буде оберігати тебе.","Головне — мудрість: здобувай мудрість, і всім майном твоїм здобувай розум.","Високо цінуй її, і вона піднесе тебе; вона прославить тебе, якщо ти приліпишся до неї;","покладе на голову твою прекрасний вінок, доставить тобі чудовий вінець.","Слухай, сину мій, і прийми слова мої, — і примножаться тобі літа життя.","Я вказую тобі путь мудрости, веду тебе стежками прямими.","Коли підеш, не буде утрудненим хід твій, і коли побіжиш, не спіткнешся.","Міцно тримайся наставляння, не залишай, зберігай його, тому що воно — життя твоє.","Не вступай на стежку нечестивих і не ходи шляхом злих;","залиш його, не ходи ним, ухилися від нього і пройди мимо;","тому що вони не заснуть, якщо не зроблять зла; пропадає сон у них, якщо вони не доведуть кого до падіння;","бо вони їдять хліб беззаконня і п’ють вино крадіння.","Путь праведних — як світило променисте, яке більше і більше світлішає до повного дня.","Путь же беззаконних — як темрява; вони не знають, об що спіткнуться.","Сину мій! до слів моїх дослухайся, і до промов моїх прихили вухо твоє;","нехай не відходять вони від очей твоїх; зберігай їх усередині серця твого:","тому що вони життя для того, хто знайшов їх, і здоров’я для всього тіла його.","Більше за все бережене зберігай серце твоє, тому що з нього джерела життя.","Відкинь від себе облудність уст, і лукавство язика віддали від себе.","Очі твої нехай прямо дивляться, і вії твої нехай будуть спрямовані прямо перед тобою.","Обміркуй стежку для ноги твоєї, і всі путі твої нехай будуть твердими.","Не ухиляйся ні праворуч, ні ліворуч; віддали ногу твою від зла,","[тому що шляхи праві спостерігає Господь, а ліві — зіпсовані.","Він же прямими зробить путі твої, і ходу твою у мирі влаштує.]"],"x":{"4":"12.28.9","7":"29.6.18","8":"37.2.46","9":"26.1.9","10":"26.3.2","14":"25.1.1|26.1.10","16":"20.6.4|25.35.5|43.2.1","17":"26.1.13","18":"25.96.11|50.5.16","19":"4.28.29|31.59.10","22":"25.18.8","23":"50.6.1|75.13.9","25":"24.31.1|30.9.7","26":"75.12.13","27":"4.5.32"}},{"v":["Сину мій! дослухайся до мудрости моєї, і прихили вухо твоє до розуму мого,","щоб дотриматися розсудливости, і щоб вуста твої зберегли знання. [Не слухай улесливої жінки;]","тому що мед виливають вуста чужої дружини, і м’якша за єлей мова її;","але наслідки від неї гіркі, як полинь, гострі, як меч двогострий;","ноги її сходять до смерти, стопи її досягають пекла.","Якби ти захотів осягнути стежку життя її, то путі її непостійні, і ти не узнаєш їх.","Отже, діти, слухайте мене і не відступайте від слів уст моїх.","Тримай далі від неї путь твою і не підходь близько до дверей дому її,","щоб здоров’я твого не віддати іншим і років твоїх мучителеві;","щоб не насичувалися силою твоєю чужі, і труди твої не були для чужого дому.","І ти будеш стогнати після, коли плоть твоя і тіло твоє будуть виснажені, —","і скажеш: «навіщо я ненавидів наставляння, і серце моє зневажало викривання,","і я не слухав голоси вчителів моїх, не прихиляв вуха мого до наставників моїх:","ледь не впав я у всяке зло серед зібрання і суспільства!»","Пий воду з твоєї водойми і ту, яка тече з твого колодязя.","Нехай [не] розливаються джерела твої по вулиці, потоки вод — по площах;","нехай вони будуть належати тобі одному, а не чужим з тобою.","Джерело твоє нехай буде благословенним; і утішайся дружиною юности твоєї,","улюбленою ланню і прекрасною сарною: груди її нехай напувають тебе повсякчас, любов’ю її насолоджуйся постійно.","І для чого тобі, сину мій, захоплюватися сторонньою й обіймати груди чужої?","Бо перед очима Господа путі людини, і Він вимірює всі стежки її.","Беззаконного уловлюють власні беззаконня його, і в кайданах гріха свого він утримується:","він помирає без наставляння, і від великого безумства свого губиться."],"x":{"1":"26.4.20","5":"26.7.27|50.14.6","8":"26.7.25","9":"26.6.33","10":"26.29.3|30.9.6","11":"52.15.14","15":"26.9.17","18":"27.9.9","20":"30.9.10","21":"24.34.24|32.16.17","22":"25.7.17|31.5.18","23":"36.33.11"}},{"v":["Сину мій! якщо ти поручився за ближнього твого і дав руку твою за іншого, —","ти обплутав себе словами вуст твоїх, упійманий словами вуст твоїх.","Зроби ж, сину мій, ось що, і визволи себе, тому що ти потрапив до рук ближнього твого: піди, упади до ніг і благай ближнього твого;","не давай сну очам твоїм і дрімання віям твоїм;","рятуйся, як сарна з руки і як птах з руки птахолова.","Піди до мурахи, лінивцю, подивися на дії її, і будь мудрим.","Нема у неї ні начальника, ні приставника, ні володаря;","але вона заготовляє влітку хліб свій, збирає під час жнив їжу свою. [Або піди до бджоли і пізнай, яка вона працьовита, яку поважну роботу вона виконує; її труди вживають для здоров’я і царі і простолюдини; улюблена ж вона всіма і славна; хоч силою вона слабка, але мудрістю вшанована.]","Доки ти, лінивцю, будеш спати? коли ти встанеш від сну твого?","Трохи поспиш, трохи подрімаєш, трохи, склавши руки, полежиш:","і прийде, як перехожий, бідність твоя, і нестаток твій, як розбійник. [Якщо ж будеш не лінивим, то, як джерело, прийдуть жнива твої; убогість же далеко втече від тебе.]","Людина лукава, людина нечестива ходить з облудними вустами,","моргає очима своїми, говорить ногами своїми, дає знаки пальцями своїми;","підступність у серці її: вона замишляє зло повсякчас, сіє розбрат.","Зате несподівано прийде погибель її, раптом буде розбита — без зцілення.","Ось шість, що ненавидить Господь, навіть сім, що мерзота для душі Його:","очі горді, мова неправдива і руки, що проливають кров невинну,","серце, яке кує злі задуми, ноги, які швидко біжать до лиходійства,","лжесвідок, який наговорює неправду і сіє розбрат між братами.","Сину мій! зберігай заповідь батька твого і не відкидай наставляння матері твоєї;","нав’яжи їх назавжди на серце твоє, обв’яжи ними шию твою.","Коли ти підеш, вони будуть керувати тобою; коли ляжеш спати, будуть охороняти тебе; коли пробудишся, будуть розмовляти з тобою:","бо заповідь є світильник, і наставляння — світло, і розсудливі повчання — шлях до життя,","щоб оберігати тебе від негідної жінки, від улесливої мови чужої.","Не пожадай краси її в серці твоєму, [нехай не уловленим будеш очима твоїми,] і нехай не захопить вона тебе віями своїми;","тому що через жінку блудну убожіють до шматка хліба, а заміжня жінка уловлює дорогу душу.","Чи може хто взяти собі вогонь у пазуху, щоб не прогорів одяг його?","Чи може хто ходити по вугіллю, яке горить, щоб не обпекти ніг своїх?","Те саме буває і з тим, хто входить до дружини ближнього свого: хто доторкнеться до неї, не залишиться без провини.","Не дарують злодієві, якщо він краде, щоб наситити душу свою, коли він голодний;","але, будучи упійманим, він заплатить всемеро, віддасть усе майно дому свого.","Хто ж перелюбствує з жінкою, у того немає розуму; той губить душу свою, хто чинить це:","побиття і ганьбу знайде він, і нечестя його не згладиться,","тому що ревнощі — лють чоловіка, і не пощадить він у день помсти,","не прийме ніякого викупу і не задовольниться, скільки б ти не примножував дари."],"x":{"1":"30.29.18","3":"30.29.21","4":"25.131.4","5":"25.123.7","9":"26.26.14","10":"26.24.33","13":"26.10.10","14":"26.17.20","15":"25.57.9","17":"26.30.13","19":"26.19.5","20":"26.1.8","21":"4.6.8","22":"26.3.23","23":"25.118.105|57.1.19","24":"26.7.5","25":"30.9.8","26":"26.5.10","29":"75.13.4","31":"1.22.1","32":"2.20.10"}},{"v":["Сину мій! зберігай слова мої і заповіді мої приховай у себе. [Сину мій! шануй Господа, — і зміцнишся, і, крім Нього, не бійся нікого.]","Зберігай заповіді мої і живи, і вчення моє, як зіниця очей твоїх.","Нав’яжи їх на персти твої, напиши їх на скрижалі серця твого.","Скажи мудрості: «ти сестра моя!» і розум назви рідним твоїм,","щоб вони охороняли тебе від дружини іншого, від чужої, яка пом’якшує слова свої.","Ось, одного разу дивився я у вікна дому мого, крізь ґрати мої,","і побачив серед недосвідчених, помітив між молодими людьми нерозумного юнака,","який переходив площу біля рогу її і йшов по дорозі до дому її,","у сутінках під вечір дня, у нічній темряві і в мороці.","І ось — назустріч йому жінка, в убранні блудниці, з підступним серцем,","галаслива і невгамовна; ноги її не живуть у домі її:","то на вулиці, то на площах, і біля кожного рогу чинить вона кови.","Вона схопила його, цілувала його, і з безсоромним обличчям говорила йому:","«мирна жертва у мене: сьогодні я звершила обітниці мої;","тому і вийшла назустріч тобі, щоб відшукати тебе, і — знайшла тебе;","килимами я вбрала постіль мою, різнобарвними тканинами єгипетськими;","спальню мою напахтила смирною, алое і корицею;","зайди, будемо упиватися ніжностями до ранку, насолодимося любов’ю,","тому що чоловіка немає вдома: він вирушив у далеку дорогу;","гаманець срібла взяв із собою; прийде додому до дня повномісяччя».","Численними ласкавими словами вона звабила його, м’якістю вуст своїх оволоділа ним.","Негайно він пішов за нею, як віл йде на забій, [і як пес — на ланцюг,] і як олень — на постріл,","доки стріла не простромить печінки його; як пташка кидається в тенета, і не знає, що вони — на погибель її.","Отже, діти, слухайте мене і дослухайтеся до слів моїх.","Нехай не ухиляється серце твоє на путі її, не блукай по стежках її,","тому що багатьох повалила вона пораненими, і багато сильних убиті нею:","дім її — дорога у пекло, яка сходить у внутрішні оселі смерти."],"x":{"2":"2.18.5","3":"4.6.8","4":"29.8.2","5":"26.6.24","23":"26.1.17","25":"24.31.9","27":"26.5.5"}},{"v":["Чи не премудрість взиває? і чи не розум підносить голос свій?","Вона стає на підвищених місцях, при шляху, на роздоріжжях;","вона взиває біля воріт при вході в місто, біля входу в двері:","«до вас, люди, взиваю я, і до синів людських голос мій!","Навчіться, нерозумні, розсудливости, і дурні — розуму.","Слухайте, тому що я буду говорити важливе, і слова вуст моїх — правда;","бо істину промовить язик мій, і нечестя — мерзота для вуст моїх;","усі слова вуст моїх справедливі; немає у них підступу і лукавства;","усі вони ясні для розумного і справедливі для тих, що здобули знання.","Прийміть учення моє, а не срібло; краще знання, ніж добірне золото;","тому що мудрість краща за перли, і ніщо з бажаного не зрівняється з нею.","Я, премудрість, живу з розумом і шукаю розсудливого знання.","Страх Господній — ненавидіти зло; гордість і зарозумілість і злу путь і підступні вуста я ненавиджу.","У мене рада і правда; я розум, у мене сила.","Мною царі царюють і володарі узаконюють правду;","мною керуються начальники і вельможі й усі судді землі.","Тих, хто любить мене, я люблю, і ті, що шукають мене, знайдуть мене;","багатство і слава у мене, скарб, що не гине, і правда;","плоди мої кращі за золото, і золото найчистіше, і користи від мене більше, ніж від добірного срібла.","Я ходжу шляхом правди, стежками правосуддя,","щоб доставити тим, хто любить мене, істотне благо, і скарбниці їхні я наповнюю. [Коли я звіщу те, що буває щодня, то не забуду перелічити те, що від віку.]","Господь мав мене початком путі Своєї, раніше творінь Своїх, споконвіку;","від віку я помазана, від початку, раніше буття землі.","Я народилася, коли ще не існували безодні, коли ще не було джерел, повних води.","Я народилася раніше, ніж підняті були гори, раніше пагорбів,","коли ще Він не створив ні землі, ні полів, ні початкових порошинок всесвіту.","Коли Він готував небеса, я була там. Коли Він проводив кругову лінію по лицю безодні,","коли утверджував угорі хмари, коли зміцнював джерела безодні,","коли давав морю устав, щоб води не переступали меж його, коли покладав основи землі:","тоді я була при Ньому художницею, і була радістю кожного дня, веселячись перед лицем Його в усі часи,","радіючи на земному колі Його, і радість моя була із синами людськими.","Отже, діти, послухайте мене; і блаженні ті, які зберігають путі мої!","Послухайте настанови і будьте мудрі, і не відступайте від них.","Блаженна людина, яка слухає мене, пильнуючи щодня біля воріт моїх і стоячи на сторожі біля дверей моїх!","тому що, хто знайшов мене, той знайшов життя, і одержить благодать від Господа;","а той, хто грішить проти мене, наносить шкоду душі своїй: усі ненависники мої люблять смерть»."],"x":{"1":"30.24.1|50.11.19|63.1.24","5":"25.91.7","6":"50.7.29","7":"53.8.46","8":"25.11.7","10":"24.28.15|26.3.14|29.7.9","11":"24.28.16","12":"52.11.49","13":"30.1.18:25","15":"0.49.10|37.2.21|62.13.1","18":"26.3.16","19":"24.28.17|29.7.9","22":"29.9.9|30.24.10|53.1.1","25":"25.89.3|25.109.3","28":"24.26.8|24.36.29","29":"24.38.10","30":"53.5.20","31":"53.1.10","32":"25.118.1-2|52.11.28","34":"30.14.24|51.3.20"}},{"v":["Премудрість збудувала собі дім, витесала сім стовпів його,","заколола жертву, розбавила вино своє і приготувала в себе трапезу;","послала слуг своїх проголосити з височин міських:","«хто нерозумний, звернися сюди!» І бідним на розум вона сказала:","«йдіть, їжте хліб мій і пийте вино, мною розчинене;","залиште нерозумне, і живіть, і ходіть шляхом розуму».","Той, хто повчає кощунника, наживе собі неславу, і той, хто викриває нечестивого — пляму собі.","Не викривай кощунника, щоб він не зненавидів тебе; викривай мудрого, і він полюбить тебе;","дай наставляння мудрому, і він буде ще мудрішим; навчи правдивого, і він примножить знання.","Початок мудрости — страх Господній, і пізнання Святого — розум;","тому що через мене примножаться дні твої, і додадуться тобі роки життя.","[Сину мій!] якщо ти мудрий, то мудрий для себе [і для ближніх твоїх]; і якщо буйний, то один потерпиш. [Хто утверджується на неправді, той пасе вітер, той ганяється за птахами летючими: бо він залишив путі свого виноградника і блукає стежками поля свого; проходить через безводну пустелю і землю, приречену на спрагу; збирає руками безплідне.]","Жінка безрозсудна, галаслива, нерозумна, яка нічого не знає,","сідає біля дверей дому свого на стільці, на підвищених місцях міста,","щоб кликати тих, що проходять дорогою, йдуть прямо своїми шляхами:","«хто нерозумний, звернися сюди!» і бідному розумом сказала вона:","«води вкрадені солодкі, і прихований хліб приємний».","І він не знає, що мерці там, і що у глибині пекла закликані нею. [Але ти відскоч, не барися на місці, не зупиняй погляду твого на ній; бо таким чином ти пройдеш воду чужу. Від води чужої віддаляйся, і з джерела чужого не пий, щоб пожити довгий час, і щоб додалися тобі літа життя.]"],"x":{"1":"71.3.15|75.3.6|76.3.12","3":"52.14.16","4":"50.11.25|63.1.27","5":"53.6.48|31.55.1","6":"73.2.12","8":"26.15.12|50.7.6","9":"26.27.6","10":"26.1.7","11":"26.10.27","17":"26.20.17|30.23.23","18":"26.7.27"}},{"v":["Притчі Соломона. Син мудрий радує батька, а син нерозумний — засмучення для його матері.","Не приносять користи скарби неправедні, правда ж рятує від смерти.","Не допустить Господь терпіти голод душі праведного, надбання ж нечестивих вивергне.","Лінива рука робить бідним, а рука старанна збагачує.","Хто збирає влітку — син розумний, а хто спить під час жнив — син безпутний.","Благословення — на голові праведника, вуста ж беззаконних загородить насильство.","Пам’ять праведника буде благословенна, а ім’я нечестивих мерзотним.","Мудрий серцем приймає заповіді, а нерозумний устами спотикнеться.","Хто ходить у непорочності, той ходить безпечно; а хто спотворює путі свої, той буде покараний.","Хто мигає очима, той викликає досаду, а нерозумний устами спотикнеться.","Вуста праведника — джерело життя, вуста ж беззаконних загородить насильство.","Ненависть збуджує розбрати, але любов покриває всі гріхи.","У вустах розумного знаходиться мудрість, але на тілі нерозумного — різка.","Мудрі зберігають знання, але вуста нерозумного — близька загибель.","Майно багатого — міцне місто його, біда для бідних — убогість їх.","Труди праведного — до життя, успіх нечестивого — до гріха.","Хто зберігає настановлення, той на путі до життя; а той, хто відкидає викривання, — блукає.","Хто приховує ненависть, у того вуста неправдиві; і хто розголошує наклепи, той нерозумний.","При багатослів’ї не минути гріха, а той, хто стримує вуста свої, — розумний.","Добірне срібло — язик праведного, серце ж нечестивих — нікчемність.","Уста праведного пасуть багатьох, а нерозумні помирають від нестачі розуму.","Благословення Господнє — воно збагачує і печалі з собою не приносить.","Для нерозумного злочинне діяння ніби забава, а людині розумній властива мудрість.","Чого страшиться нечестивий, те й осягне його, а бажання праведників виконається.","Як проноситься вихор, так немає більше нечестивого; а праведник — на вічній основі.","Що оцет для зубів і дим для очей, те лінивий для тих, хто посилає його.","Страх Господній додає днів, літа ж нечестивих скоротяться.","Очікування праведників — радість, а надія нечестивих загине.","Путь Господня — твердиня для непорочного і страх для тих, що чинять беззаконня.","Праведник повіки не завагається, нечестиві ж не будуть жити на землі.","Вуста праведника виточують мудрість, а язик зловредний відсічеться.","Вуста праведного знають благоприємне, а вуста нечестивих — розбещене."],"x":{"1":"26.15.20","2":"26.11.4|24.20.20","3":"25.32.19|31.49.26","4":"26.21.5","7":"25.111.6|30.44.13|50.26.13","8":"25.140.5|55.3.17","10":"26.6.13|30.27.24","12":"56.4.8|63.3.4","15":"26.18.11","17":"26.12.1","19":"27.10.14|30.20.7","21":"50.12.35","25":"25.36.36","28":"24.8.13|25.111.10"}},{"v":["Невірні терези — мерзота перед Господом, але правильна вага угодна Йому.","Прийде гордість, прийде і посоромлення; але зі смиренними — мудрість. [Праведник, помираючи, залишає жаль; але несподівана і радісна буває погибель нечестивих.]","Непорочність прямодушних буде керувати ними, а лукавство підступних погубить їх.","Не допоможе багатство у день гніву, правда ж урятує від смерти.","Правда непорочного рівняє путь його, а нечестивий упаде від нечестя свого.","Правда прямодушних спасе їх, а беззаконники будуть уловлені беззаконням своїм.","Зі смертю чоловіка нечестивого зникає надія, і чекання беззаконних гине.","Праведник спасається від біди, а замість нього потрапляє у неї нечестивий.","Устами лицемір губить ближнього свого, а праведники прозорливістю спасаються.","При благоденстві праведників веселиться місто, і при погибелі нечестивих буває торжество.","Благословенням праведних звеличується місто, а вустами нечестивих руйнується.","Бідний на розум висловлює презирство до ближнього свого; але розумна людина мовчить.","Хто ходить як пліткар, той відкриває таємницю; але вірна людина таїть справу.","При нестачі піклування падає народ, а при багатьох радниках благоденствує.","Зло заподіює собі той, хто дає запоруку за стороннього; а хто ненавидить запоруку, той безпечний.","Доброзвичайна дружина здобуває славу [чоловіку, а дружина, що ненавидить правду, є верх нечестя. Лінивці бувають убогі], а працелюбні, здобувають багатство.","Чоловік милосердий благодіє душі своїй, а жорстокосердий руйнує плоть свою.","Нечестивий робить справу ненадійну, а тому, хто сіє правду, — нагорода певна.","Праведність веде до життя, а той, хто прагне до зла, прагне смерти своєї.","Мерзота перед Господом — підступні серцем; але благоугодні Йому непорочні в путі.","Можна ручитися, що порочний не залишиться непокараним; сім’я ж праведних спасеться.","Що золоте кільце в носі у свині, те жінка красива і — нерозсудлива.","Бажання праведних є одне добро, очікування нечестивих — гнів.","Хтось сипле щедро, і йому ще додається; а інший надміру ощадливий, і однак же убожіє.","Благодійна душа буде насичена, і хто напуває інших, той і сам напоєний буде.","Хто утримує в себе хліб, того кляне народ; а на голові того, хто продає, — благословення.","Хто прагне добра, той шукає благовоління; а хто шукає зла, до того воно і приходить.","Той, хто надіється на багатство своє, упаде; а праведники, як лист, будуть зеленіти.","Той, хто розладнує дім свій, отримає у наділ вітер, і нерозумний буде рабом мудрого серцем.","Плід праведника — древо життя; і мудрий привертає душі.","Так праведнику воздається на землі, тим більше нечестивому і грішному."],"x":{"1":"4.25.13","4":"26.10.2|30.5.10|36.7.19|46.1.18","6":"29.5.15","8":"20.7.9|25.33.20","10":"26.28.12","11":"0.18.32|30.16.5","13":"26.20.19|30.27.17","14":"26.15.22|29.6.26","18":"65.6.8","20":"25.5.7|25.118.1","21":"26.16.5","23":"25.111.10","24":"64.9.6","28":"24.31.25|50.19.23|71.6.17","30":"26.3.18","31":"56.4.18"}},{"v":["Хто любить настанови, той любить знання; а хто ненавидить викриття, той невіглас.","Добрий здобуває благовоління від Господа; а людину підступну Він засудить.","Не утвердить себе людина беззаконням; корінь же праведників нерухомий.","Доброчесна дружина — вінець для чоловіка свого; а ганебна — як гниль у кістках його.","Помисли праведних — правда, а задуми нечестивих — підступність.","Промови нечестивих — засідка для пролиття крови, вуста ж праведних спасають їх.","Торкнеться нечестивих нещастя — і немає їх, а дім праведних стоїть.","Хвалять людину за мірою розуму її, а розбещений серцем буде у презирстві.","Краще простий, але який працює на себе, ніж той, хто видає себе за знатного, але має потребу у хлібі.","Праведний турбується і про життя худоби своєї, серце ж нечестивих жорстоке.","Хто обробляє землю свою, той буде насичуватися хлібом; а хто йде слідом за тими, що марно гають час, той недоумкуватий. [Хто знаходить задоволення у гаянні часу за вином, той у своєму домі залишить безславність.]","Нечестивий бажає уловити в сіті зла; але корінь праведних твердий.","Нечестивий уловлюється гріхами вуст своїх; але праведник вийде з біди. [Той, хто дивиться лагідно, помилуваний буде, а той, хто зустрічається у воротах, заважає іншим.]","Від плоду вуст своїх людина насичується добром, і нагорода людині — за ділами рук її.","Шлях нерозумного прямий у його очах; але хто слухає поради, той мудрий.","У нерозумного відразу ж виявиться гнів його, а розсудливий ховає образу.","Хто говорить те, що знає, той говорить правду; а у свідка неправдивого — омана.","Якийсь пустослів уражає наче мечем, а язик мудрих — лікує.","Вуста правдиві вічно перебувають, а неправдивий язик — тільки на мить.","Підступність — у серці зловмисників, радість — у миротворців.","Не станеться з праведником ніякого зла, нечестиві ж будуть сповнені злом.","Мерзота перед Господом — вуста неправдиві, а ті, що говорять істину, благоугодні Йому.","Чоловік розсудливий приховує знання, а серце нерозумних висловлює глупоту.","Рука старанних буде панувати, а лінива буде під даниною.","Туга на серці людини придушує її, а добре слово звеселяє його.","Праведник указує ближньому своєму путь, а путь нечестивих вводить їх в оману.","Лінивий не смажить своєї дичини; а майно людини старанної дорогоцінне.","На путі правди — життя, і на стежці її немає смерти."],"x":{"1":"26.10.17","3":"26.10.25|31.37.31|32.17.8","6":"26.1.11","10":"4.22.6|4.25.4","11":"26.28.19|30.20.28","13":"26.18.7","14":"25.61.13","15":"26.10.17","16":"27.7.9","17":"26.14.5","18":"25.58.8|25.63.4","22":"25.5.7","23":"26.13.17"}},{"v":["Мудрий син слухає настанови батька, а буйний не слухає викриття.","Від плоду вуст своїх людина споживе добро, душа ж законопорушників — зло.","Хто зберігає вуста свої, той береже душу свою; а хто широко розкриває свій рот, тому біда.","Душа лінивого бажає, але марно; а душа старанних насититься.","Праведник ненавидить неправдиве слово, а нечестивий осоромлює і нечестить себе.","Правда зберігає непорочного в путі, а нечестя губить грішника.","Хтось видає себе за багатого, а в нього нічого нема; інший видає себе за бідного, а в нього багатства багато.","Багатством своїм людина викуповує життя своє, а бідний і погрози не чує.","Світло праведних весело горить, світильник же нечестивих угасає. [Душі підступні блукають у гріхах, а праведники співчувають і милують.]","Від зарозумілости виникає розбрат, а в тих, що радяться, — мудрість.","Багатство від суєтности виснажується, а той, хто збирає працею, примножує його.","Надія, яка довго не збувається, мучить серце, а бажання, що сповнилося, — як древо життя.","Хто нехтує слово, той заподіює шкоду собі; а хто боїться заповіді, тому воздається.","[У сина лукавого нічого немає доброго, а в розумного раба справи благоуспішні, і путь його пряма.]","Навчання мудрого — джерело життя, що віддаляє від сітей смерти.","Добрий розум дає приємність, путь же беззаконних жорстока.","Усякий розважливий діє зі знанням, а нерозумний виставляє напоказ глупство.","Поганий посол потрапляє в біду, а вірний посланник — спасіння.","Убогість і посоромлення тому, хто відкидає вчення; а хто дотримується настанов, буде в честі.","Бажання, яке сповнилося, — приємне для душі; але тяжко для глупих ухилятися від зла.","Той, хто спілкується з мудрими, стане мудрішим, а хто дружить з нерозумними, розбеститься.","Грішників переслідує зло, а праведникам відплачується добром.","Добрий залишає спадщину й онукам, а багатство грішника зберігається для праведного.","Багато хліба буває і на ниві бідних; але дехто гине від безладдя.","Хто шкодує різки своєї, той ненавидить сина; а хто любить, той з дитинства карає його.","Праведник їсть до ситости, а утроба беззаконних терпить нестачу."],"x":{"1":"26.15.12","2":"26.12.14","3":"26.18.21|56.3.10","4":"26.21.25","5":"25.118.163","7":"26.12.9","8":"26.10.15","9":"26.24.20|25.36.21","11":"26.28.8","13":"26.1.24|38.4.6","15":"26.10.11","21":"30.6.35|30.37.15","23":"24.27.17","25":"26.23.13|30.30.1","26":"31.65.13|30.37.32"}},{"v":["Мудра дружина влаштує дім свій, а нерозумна зруйнує його своїми руками.","Хто йде прямим шляхом, боїться Господа; а чиї шляхи криві, той нехтує Його.","У вустах нерозумного — бич гордости; вуста ж мудрих охороняють їх.","Де немає волів, там ясла порожні; а багато прибутку від сили волів.","Вірний свідок не обманює, а свідок неправдивий наговорить багато неправди.","Розпусний шукає мудрости, і не знаходить; а для розумного знання легке.","Відійди від чоловіка нерозумного, у якого ти не помічаєш розумних уст.","Мудрість розумного — знання путі своєї, глупство ж безрозсудних — омана.","Нерозумні глузують з гріха, а серед праведних — благовоління.","Серце знає горе душі своєї, і в радість його не втрутиться чужий.","Дім беззаконних зруйнується, а житло праведних розквітне.","Є шляхи, які здаються людині прямими; але кінець їх — дорога до смерти.","І під час сміху іноді болить серце, і кінцем радости буває печаль.","Людина з розбещеним серцем насититься від шляхів своїх, і добра — від своїх.","Нерозумний вірить усякому слову, розсудливий же уважний до шляхів своїх.","Мудрий боїться і віддаляється від зла, а нерозумний дратівливий і самовпевнений.","Запальний може зробити дурість; але людина, яка навмисне чинить зло, ненависна.","Невігласи одержують у частку собі глупоту, а розсудливі увінчаються знанням.","Схиляться злі перед добрими і нечестиві — біля воріт праведника.","Бідний ненавидимим буває навіть близькими своїми, а в багатого багато друзів.","Хто з презирством ставиться до ближнього свого, той грішить; а хто милосердний до бідних, той блаженний.","Чи не помиляються ті, що замишляють зло? [не знають милости і вірности ті, що чинять зло;] але милість і вірність у благомислячих.","Від усякої праці є прибуток, а від марнослів’я тільки збиток.","Вінець мудрих — багатство їх, а глупота невігласів глупотою і є.","Вірний свідок спасає душі, а неправдивий наговорить багато неправди.","У страху перед Господом — надія тверда, і синам Своїм Він притулок.","Страх Господній — джерело життя, що віддаляє від сітей смерти.","У численності народу — велич царя, а при малолюдстві народу біда володареві.","У терплячої людини багато розуму, а дратівливий виявляє глупоту.","Лагідне серце — життя для тіла, а заздрість — гниль для кісток.","Хто пригноблює бідного, той хулить Творця його; хто ж шанує Його, той благодіє нужденному.","За зло своє нечестивий буде відкинутий, а праведний і при смерті своїй має надію.","Мудрість спочиває у серці розумного, і серед дурнів дає знати про себе.","Праведність підносить народ, а беззаконня — нечестя народів.","Благовоління царя — до раба розумного, а гнів його — проти того, хто ганьбить його."],"x":{"1":"26.12.4|26.24.3","2":"24.12.24","3":"55.3.5|26.12.6","5":"1.23.1|26.12.17","6":"30.1.30","8":"25.138.24","11":"26.12.7","12":"26.16.25","14":"31.3.10-11","15":"62.16.18|58.4.1","16":"25.110.10","17":"26.12.16","18":"66.5.15","19":"31.60.14","20":"26.19.7","21":"25.40.2|50.5.7","23":"26.12.11","25":"26.12.17","26":"26.18.11","27":"26.10.17:27|9.22.6","29":"26.19.11","31":"26.17.5|50.25.36","32":"24.21.17|25.72.18|25.111.8","34":"26.11.11|29.5.24","35":"52.7.2|62.13.3"}},{"v":["[Гнів губить і розумних.] Лагідна відповідь відвертає гнів, а образливе слово збуджує лють.","Язик мудрих сповіщає добрі знання, а вуста нерозумних вивергають дурість.","На всякому місці очі Господні: вони бачать злих і добрих.","Лагідний язик — древо життя, але неприборканий — печаль духу.","Нерозумний нехтує наставляння батька свого; а хто прислуховується до викривань, той розважливий. [У багатстві правди велика сила, а нечестиві викоріняться з землі.]","У домі праведника — достаток скарбів, а у прибутку нечестивого — безладдя.","Вуста мудрих поширюють знання, а серце нерозумних не так.","Жертва нечестивих — мерзота перед Господом, а молитва праведних благоугодна Йому.","Мерзота перед Господом — путь нечестивого, а того, хто йде шляхом правди, Він любить.","Зле покарання — тому, хто ухиляється від путі, і той, хто ненавидить викриття, загине.","Пекло й Аваддон відкриті перед Господом, тим більше серця синів людських.","Не любить розпусний тих, хто викриває його, і до мудрих не піде.","Веселе серце робить лице веселим, а при сердечній печалі дух занепадає.","Серце розумного шукає знання, вуста ж дурних споживають глупство.","Усі дні нещасного сумні; а в кого серце веселе, у того завжди бенкет.","Краще небагато зі страхом Господнім, ніж великий скарб, і при ньому тривога.","Краще блюдо зелені, і при ньому любов, ніж відгодований бик, і при ньому ненависть.","Запальна людина збуджує розбрат, а терпляча утишує незгоду.","Шлях лінивого — як терновий пліт, а путь праведних — гладенька.","Мудрий син радує батька, а нерозумна людина зневажає матір свою.","Глупота — радість для недоумкуватого, а людина розумна йде прямою дорогою.","Без ради розпочаті діла зруйнуються, а з великою кількістю радників вони відбудуться.","Радість людині у відповіді вуст її, і як добре слово вчасне!","Путь життя мудрого вгору, щоб ухилитися від пекла внизу.","Дім гордовитих розорить Господь, а межу вдови укріпить.","Мерзота перед Господом — думки злих, слова ж непорочних угодні Йому.","Корисливий розладнає дім свій, а той, хто ненавидить подарунки, буде жити.","Серце праведного обмірковує відповідь, а вуста нечестивих вивергають зло. [Приємні перед Господом путі праведних; через них і вороги стають друзями.]","Далекий Господь від нечестивих, а молитву праведників чує.","Світлий погляд радує серце, добра звістка зміцнює кістки.","Вухо, уважне до вчення життя, перебуває між мудрими.","Хто відкидає наставляння, той не дбає про свою душу; а хто слухає викривання, той набуває розуму.","Страх Господній навчає мудрости, і славі передує смирення."],"x":{"1":"8.25.24:35|26.15.28","2":"26.12.23","3":"25.32.14|75.4.13","4":"26.3.18|26.11.30|26.12.18","6":"25.111.3|24.20.22","8":"26.21.27|30.34.19|31.1.11|32.6.20|40.5.21","9":"25.5.7","11":"24.26.6|25.7.10","13":"26.17.22|30.38.18","15":"27.3.12","16":"25.36.16","17":"26.17.1","18":"26.26.21","19":"58.2.10","20":"26.10.1|26.17.25|26.19.13:26","22":"26.11.14|26.20.18","25":"20.7.9","27":"71.6.9|1.23.8","29":"25.10.5|31.1.15|55.5.16"}},{"v":["Людині належать припущення серця, але від Господа відповідь язика.","Усі путі людини чисті в її очах, але Господь зважує душі.","Віддай Господу справи твої, і наміри твої звершаться.","Усе зробив Господь заради Себе; і навіть нечестивого тримає на день біди.","Мерзота перед Господом усякий гордовитий серцем; можна ручитися, що він не залишиться непокараним. [Початок доброго шляху — чинити правду; це угодніше перед Богом, ніж приносити жертви. Хто шукає Господа, знайде знання з правдою; істинно ті, що шукають Його, знайдуть мир.]","Милосердям і правдою очищається гріх, і страх Господній відводить від зла.","Коли Господу вгодні путі людини, Він і ворогів її примиряє з нею.","Краще небагато з правдою, ніж безліч прибутків з неправдою.","Серце людини обмірковує свій шлях, але Господь керує ходом її.","У вустах царя — слово натхненне; вуста його не повинні погрішати на суді.","Правильні терези і вагові чаші — від Господа; від Нього ж усі гирі в торбі.","Мерзота для царів — діло беззаконне, тому що правдою утверджується престіл.","Приємні царю вуста правдиві, і того, хто говорить істину, він любить.","Царський гнів — вісник смерти; але мудра людина умилостивить його.","У світлому погляді царя — життя, і благовоління його — як хмара з пізнім дощем.","Придбання мудрости набагато краще за золото, і придбання розуму переважніше за добірне срібло.","Путь праведних — відхилення від зла: той береже душу свою, хто зберігає путь свою.","Погибелі передує гордість, і падінню — пихатість.","Краще смирятися духом з лагідними, ніж розділяти здобич з гордими.","Хто веде справу розумно, той знайде благо, і хто надіється на Господа, той блаженний.","Мудрий серцем назветься благорозумним, і солодкі слова додасть до навчання.","Розум для тих, хто має його, — джерело життя, а вченість нерозумних — глупота.","Серце мудрого робить язик його мудрим і примножує знання у вустах його.","Приємна мова — стільниковий мед, солодка для душі і цілюща для кісток.","Є путі, які здаються людині прямими, але кінець їх шлях до смерті.","Трудящий трудиться для себе, тому що змушує його до того рот його.","Чоловік лукавий замишляє зло, і на вустах його ніби вогонь палючий.","Чоловік підступний сіє розбрат, і навушник розлучає друзів.","Людина неблагонамірена розбещує ближнього свого і веде його на путь недобру;","прищулює очі свої, щоб придумати підступи; закушуючи собі губи, чинить лиходійство; [він — піч злоби].","Вінець слави — сивина, яка знаходиться на шляху правди.","Довготерпеливий краще за хороброго, і той, хто володіє собою, краще за завойовника міста.","У полу кидається жереб, але всі рішення його — від Господа."],"x":{"1":"32.10.23","3":"25.36.5|56.5.7","4":"24.21.30|62.11.36","5":"26.8.13","6":"17.5.15","7":"30.6.17|56.3.13","10":"10.3.27","11":"26.11.1|26.20.10:23","12":"26.20.28|26.25.5","14":"20.7.7|26.20.2","16":"24.28.15","18":"20.3.1|26.18.13|37.4.27","20":"25.33.9|31.30.18|32.17.7","25":"26.14.12","27":"25.7.16|55.3.6","28":"26.15.18","30":"26.6.13|26.10.10","31":"26.20.29|73.2.2","32":"26.19.11","33":"5.7.14"}},{"v":["Краще шматок сухого хліба, і з ним мир, ніж дім, повний заколотої худоби, з розбратом.","Розумний раб панує над безпутним сином і між братами розділить спадщину.","Плавильня — для срібла, і горно — для золота, а серця випробовує Господь.","Злодій дослухається до вуст беззаконних, неправдомовець слухається язика пагубного.","Хто знущається з убогого, той хулить Творця його; хто радіє нещастю, той не залишиться непокараним [а милосердий помилуваний буде].","Вінець старих — сини синів, і слава дітей — батьки їхні. [У вірного цілий світ багатства, а в невірного — ні гроша.]","Непристойна для нерозумного поважна мова, тим більше знатному — вуста неправдиві.","Подарунок — дорогоцінний камінь в очах того, хто володіє ним: куди не звернеться він, матиме успіх.","Хто прикриває провину, той шукає любови; а хто знову нагадує про неї, той віддаляє друга.","На розумного сильніше діє догана, ніж на дурня сто ударів.","Підбурювач шукає тільки зла; тому жорстокий ангел буде посланий проти нього.","Краще зустріти людині ведмедицю, позбавлену дітей, ніж дурня з його глупотою.","Хто за добро відплачує злом, від дому того не відійде зло.","Початок сварки — як прорив води; залиш сварку раніше, ніж розгориться вона.","Хто виправдовує нечестивого і хто звинувачує праведного — обоє мерзота перед Господом.","До чого скарб у руках нерозумного? Для придбання мудрости у нього немає розуму. [Хто високим робить свій дім, той шукає, як розбитися; а хто ухиляється від навчання, впаде в біди.]","Друг любить повсякчас і, як брат, з’явиться під час нещастя.","Чоловік бідний на розум дає руку і ручається за ближнього свого.","Хто любить сварки, той любить гріх, і хто високо піднімає ворота свої, той шукає падіння.","Підступне серце не знайде добра, і лукавий язик потрапить у біду.","Породив хто дурня, — собі на лихо, і батько нерозумного не порадіє.","Веселе серце доброчинне, як лікування, а сумовитий дух сушить кістки.","Нечестивий бере подарунок з пазухи, щоб викривити путі правосуддя.","Мудрість — перед лицем розумного, а очі дурня — на краю землі.","Нерозумний син — досада батькові своєму і засмучення для матері своєї.","Недобре й звинувачувати правого, і бити вельмож за правду.","Розумний стриманий у словах своїх, і розсудливий холоднокровний.","І нерозумний, коли мовчить, може здатися мудрим, і хто закриває вуста свої — розсудливим."],"x":{"1":"26.15.17","2":"30.10.28","3":"26.27.21|30.2.5|32.17.10","5":"26.14.31","6":"25.127.6|72.1.5","9":"26.10.12|30.6.5","13":"4.32.35|56.3.9|62.12.17:19|69.5.15","15":"26.24.24|31.5.23","17":"26.18.25|30.12.8-9","18":"26.6.1|26.11.15","20":"26.6.14","21":"26.15.20","22":"26.15.13","23":"26.21.14","24":"27.2.14|27.8.1","25":"26.15.20","27":"55.1.19"}},{"v":["Примхи шукає норовистий, повстає проти всього розумного.","Дурень не любить знання, а тільки б виявити свій розум.","З приходом нечестивого приходить і презирство, а з неславою — ганьба.","Слова вуст людських — глибокі води; джерело мудрости — струменевий потік.","Недобре бути небезстороннім до нечестивого, щоб звергнути праведного на суді.","Вуста нерозумного йдуть на сварку, і слова його викликають побиття.","Язик нерозумного — загибель для нього, і вуста його — сітка для душі його.","[Лінивого долає страх, а душі жоноподібні будуть голодувати.]","Слова навушника — як ласощі, і вони входять у нутрощі утроби.","Недбайливий у роботі своїй — брат марнотратцю.","Ім’я Господа — міцна вежа: втікає до неї праведник — і у безпеці.","Майно багатого — міцне місто його, і як висока огорожа в його уяві.","Перед падінням підноситься серце людини, а смирення передує славі.","Хто дає відповідь не вислухавши, той нерозумний, і сором йому.","Дух людини переносить її немочі; а вражений дух — хто може підкріпити його?","Серце розумного здобуває знання, і вухо мудрих шукає знання.","Подарунок у людини дає їй простір і до вельмож доведе її.","Перший у позові своєму правий, але приходить суперник його і досліджує її.","Жереб припиняє суперечки і вирішує між сильними.","Брат, який озлобився, неприступніший за міцне місто, і сварки подібні до запорів замку.","Від плоду вуст людини наповнюється утроба її; плодами вуст своїх вона насичується.","Смерть і життя — у владі язика, і ті, що люблять його, споживуть від плодів його.","Хто знайшов [добру] дружину, той знайшов благо й одержав благодать від Господа. [Хто виганяє добру дружину, той виганяє щастя, а хто утримує перелюбницю — божевільний і нечестивий.]","З благанням говорить убогий, а багатий відповідає грубо.","Хто хоче мати друзів, той і сам повинен бути дружнім; і буває друг, більш прив’язаний, ніж брат."],"x":{"4":"26.20.5","5":"2.19.15|4.1.17|26.24.23|30.42.1","7":"26.10.14|26.12.13","11":"25.19.2|26.14.26","12":"26.10.15","13":"26.16.18","14":"30.11.8","17":"26.17.8|50.2.11","21":"26.14.14|31.3.10","22":"26.13.3|55.3.8-10","23":"26.19.14","24":"30.13.4","25":"26.17.17"}},{"v":["Краще бідний, який ходить у своїй непорочності, ніж [багатий] із неправдивими вустами, і притім нерозумний.","Недобре душі без знання, і хто поспішний ногами, той оступиться.","Глупота людини спотворює путь її, а серце її обурюється на Господа.","Багатство додає багато друзів, а бідного залишає і друг його.","Лжесвідок не залишиться непокараним, і хто говорить неправду, не врятується.","Багато хто запобігає перед знатними, і всякий — друг людині, яка дає подарунки.","Бідного ненавидять усі брати його, тим більше друзі його віддаляються від нього: женеться за ними, щоб поговорити, але і цього немає.","Хто здобуває розум, той любить душу свою; хто спостерігає розважливість, той знаходить благо.","Лжесвідок не залишиться непокараним, і хто говорить неправду, загине.","Непристойна нерозумному пишність, тим більше рабові панування над князями.","Розсудливість робить людину повільною на гнів, і слава для неї — бути поблажливою до провин.","Гнів царя — як ревіння лева, а благовоління його — як роса на траву.","Нерозумний син — руйнування для батька свого, і сварлива дружина — стічна труба.","Дім і майно — спадщина від батьків, а розумна дружина — від Господа.","Лінощі занурюють у сонливість, і недбайлива душа буде терпіти голод.","Хто зберігає заповідь, той зберігає душу свою, а хто не дбає про путі свої, — загине.","Хто благодіє бідному, дає в борг Господу, і Він воздасть йому за благодіяння його.","Карай сина свого, доки є надія, і не обурюйся криком його.","Гнівливий нехай терпить покарання, тому що, коли пощадиш його, доведеться тобі ще більше карати його.","Слухайся поради і приймай викривання, щоб стати тобі згодом мудрим.","Багато задумів у серці людини, але відбудеться тільки визначене Господом.","Радість людині — добродійність її, і бідна людина краще, ніж неправдива.","Страх Господній веде до життя, і хто має його, завжди буде задоволений, і зло не осягне його.","Лінивий опускає руку свою у чашу, і не хоче донести її до рота свого.","Якщо ти покараєш кощунника, то і простий зробиться розсудливим; і якщо викриєш розумного, то він зрозуміє наставляння.","Хто розоряє батька і виганяє матір, — син соромітний і безчесний.","Перестань, сину мій, слухати напоумлення про відхилення від висловів розуму.","Лукавий свідок знущається із суду, і вуста беззаконних ковтають неправду.","Готові суди для кощунників, і побиття — на тіло нерозумних."],"x":{"1":"26.28.6","2":"26.6.18","3":"30.15.11|55.1.13","4":"26.14.20","5":"4.19.19|37.13.51:62","9":"26.21.28","10":"26.30.21-22","11":"26.14.29","12":"20.7.9|62.13.4","13":"26.10.1","14":"26.18.23","16":"26.3.21-22|52.11.28","17":"25.40.2|50.10.42|50.25.40","18":"26.13.25|26.23.13","21":"24.23.13|26.16.1","24":"26.26.15","25":"26.21.11","26":"26.15.20","28":"24.15.16"}},{"v":["Вино — глузливе, сикера — буйна; і всякий, хто захоплюється ними, нерозумний.","Гроза царя — ніби ревіння лева: хто дратує його, той грішить проти самого себе.","Шана для людини — відстати від сварки; а всякий дурень задерикуватий.","Лінивець узимку не оре: шукає влітку — і немає нічого.","Помисли в серці людини — глибокі води, але людина розумна вичерпує їх.","Багато хто хвалить людину за милосердя, але правдиву людину хто знаходить?","Праведник ходить у своїй непорочності: блаженні діти його після нього!","Цар, який сидить на престолі суду, розганяє очима своїми все зле.","Хто може сказати: «я очистив моє серце, я чистий від гріха мого?»","Неоднакові терези, неоднакова міра, те й інше — мерзота перед Господом.","Можна узнати навіть отрока за заняттями його, чи чистою і чи правильною буде поведінка його.","Вухо, що чує, й око, що бачить, — і те й інше створив Господь.","Не люби спати, щоб тобі не зубожіти; тримай відкритими очі твої, і будеш досита їсти хліб.","«Погано, погано», говорить покупець, а коли відійде, хвалиться.","Є золото і багато перлів, але дорогоцінне начиння — вуста розумні.","Візьми одяг його, оскільки він заручився за чужого; і за стороннього візьми від нього заставу.","Солодкий для людини хліб, придбаний неправдою; але після рот її наповниться жорствою.","Починання одержують твердість через нараду, і після наради веди війну.","Хто ходить переносником, той відкриває таємницю; і хто широко розкриває рот, з тим не спілкуйся.","Хто лихословить батька свого і свою матір, того світильник згасне серед глибокої темряви.","Спадщина, поспішно захоплена спочатку, не благословиться згодом.","Не говори: «я відплачу за зло»; залиш Господу, і Він збереже тебе.","Мерзота перед Господом — неоднакові гирі, і неправильні терези — не добро.","Від Господа спрямовуються кроки людини; людині ж як дізнатися про шлях свій?","Сітка для людини — поспішно давати обітницю, і після обітниці обмірковувати.","Мудрий цар розвіє нечестивих і поверне на них колесо.","Світильник Господній — дух людини, який випробовує всі глибини серця.","Милість і істина охороняють царя, і милістю він підтримує престіл свій.","Слава юнаків — сила їх, а прикраса старих — сивина.","Рани від побиття — лікування проти зла, й удари, що проникають у нутрощі утроби."],"x":{"1":"31.28.7|66.5.18","2":"26.19.12","5":"26.18.4","6":"50.6.2|52.18.8","7":"4.7.13","9":"10.8.46|13.6.36|24.14.4|25.50.7|30.7.5|58.1.8","10":"26.11.1","12":"1.4.11|25.93.9","16":"26.27.13","19":"26.11.13","20":"1.21.17|2.20.9|50.15.4|51.7.10","22":"26.17.13","24":"25.36.23","25":"54.5.4","26":"26.20.8","28":"26.16.12","29":"26.16.31"}},{"v":["Серце царя — у руці Господа, як потоки вод: куди захоче, туди Він направляє його.","Усякий шлях людини прямий в очах її; але Господь зважує серця.","Дотримання правди і правосуддя більш угодне Господу, ніж жертва.","Гордість очей і зарозумілість серця, які відзначають нечестивих, — гріх.","Думки старанного прагнуть достатку, а всякий поспішний терпить збиток.","Придбання скарбу неправдивим язиком — скороминучий подув тих, хто шукає смерти.","Насильство нечестивих упаде на них, тому що вони зреклися дотримуватися правди.","Мінливий шлях у людини розбещеної; а хто чистий, того дія пряма.","Краще жити в кутку на покрівлі, ніж зі сварливою дружиною у просторому домі.","Душа нечестивого бажає зла: не знайде милости в очах його і друг його.","Коли карається кощунник, простий робиться мудрим; і коли врозумляється мудрий, то він здобуває знання.","Праведник спостерігає за домом нечестивого: як впадають нечестиві у нещастя.","Хто затикає вухо своє від волання бідного, той і сам буде волати, — і не буде почутий.","Подарунок таємний гасить гнів, і дарунок у пазуху — сильну лють.","Дотримання правосуддя — радість для праведника і страх для тих, хто чинить зло.","Людина, що збилася з путі розуму, оселиться в зібранні мерців.","Хто любить веселощі, зубожіє; а хто любить вино і жир, не розбагатіє.","Викупом буде за праведного нечестивий і за прямодушного — лукавий.","Краще жити у землі пустельній, ніж з дружиною сварливою і сердитою.","Жаданий скарб і жир — у домі мудрого; а нерозумна людина марнотратить їх.","Хто дотримується правди і милости, той знайде життя, правду і славу.","Мудрий входить у місто сильних і знищує укріплення, на яке вони сподівалися.","Хто зберігає вуста свої і язик свій, той зберігає від біди душу свою.","Зарозумілий злодій — кощунник ім’я йому — діє у запалі гордости.","Жадоба лінивця уб’є його, тому що руки його відмовляються працювати;","кожного дня він сильно жадає, а праведник дає і не шкодує.","Жертва нечестивих — мерзота, особливо коли з лукавством приносять її.","Лжесвідок загине; а людина, яка говорить те, що знає, буде говорити завжди.","Людина нечестива зухвала лицем своїм, а праведний тримає прямо путь свою.","Немає мудрости, і немає розуму, і немає ради всупереч Господу.","Коня готують на день битви, але перемога — від Господа."],"x":{"1":"13.36.22","2":"26.16.2","3":"38.6.6","5":"26.10.4","9":"26.25.24","11":"26.19.25","13":"26.3.27-28","14":"8.25.18","17":"26.23.21","19":"26.25.24|30.25.21","21":"26.19.17","22":"27.9.16","26":"25.36.26","27":"26.15.8","28":"26.19.5:9","30":"36.28.5|24.5.13","31":"25.32.17"}},{"v":["Добре ім’я краще за велике багатство, і добра слава краща за срібло і золото.","Багатий і бідний зустрічаються один з одним: того й іншого створив Господь.","Розсудливий бачить біду, і ховається; а недосвідчені йдуть уперед, і караються.","За смиренням іде страх Господній, багатство і слава і життя.","Терня і сіті на шляху підступного; хто береже душу свою, віддалися від них.","Напоум юнака на початку путі його: він не ухилиться від неї, коли і постаріє.","Багатий панує над бідним, і боржник робиться рабом позикодавця.","Хто сіє неправду, пожне біду, і тростини гніву його не стане. [Людину, яка доброхітно дає, любить Бог, і нестачу діл її поповнить.]","Милосердий буде благословлятися, тому що дає бідному від хліба свого. [Перемогу і честь здобуває той, хто дає дари, і навіть оволодіває душею тих, що одержують їх.]","Прожени кощунника, і віддалиться розбрат, і припиняться сварка і лайка.","Хто любить чистоту серця, у того приємність на вустах, тому цар — друг.","Очі Господа охороняють знання, а слова законопорушника Він відкидає.","Лінивець говорить: «лев на вулиці! посередині площі уб’ють мене!»","Глибока прірва — вуста блудниць: на кого прогнівається Господь, той упаде туди.","Глупота прив’язалася до серця юнака, але виправна різка віддалить її від нього.","Хто кривдить бідного, щоб примножити своє багатство, і хто дає багатому, той зубожіє.","Прихили вухо твоє, і слухай слова мудрих, і серце твоє зверни до мого знання;","тому що утіхою буде, якщо ти будеш зберігати їх у серці твоєму, і вони будуть також на вустах твоїх.","Щоб уповання твоє було на Господа, я вчу тебе і сьогодні, і ти пам’ятай.","Чи не писав я тобі тричі в порадах і наставляннях,","щоб навчити тебе точних слів істини, щоб ти міг передавати слова істини тим, хто посилає тебе?","Не будь грабіжником бідного, тому що він бідний, і не утискуй нещасного біля воріт,","тому що Господь вступиться у справу їх і візьме душу у грабіжників їхніх.","Не дружися з гнівливим і не спілкуйся з людиною запальною,","щоб не навчитися шляхів її і не накинути петлі на душу свою.","Не будь з тих, які дають руки і ручаються за борги:","якщо тобі нема чим заплатити, то для чого доводити себе, щоб узяли постіль твою з-під тебе?","Не пересувай межі давньої, яку провели батьки твої.","Чи бачив ти людину моторну у своїй справі? Вона буде стояти перед царями, вона не буде стояти перед простими."],"x":{"1":"27.7.1-2","2":"26.29.13","3":"26.27.12","5":"5.23.13","7":"55.2.6","8":"24.4.8|38.10.12","9":"64.9.7","13":"26.26.13","20":"26.3.5-6","22":"4.24.17|24.31.13","23":"26.23.11","24":"26.15.18|26.29.22","25":"26.12.13","26":"26.6.1","27":"26.20.16","28":"4.19.14|26.23.10"}},{"v":["Коли сядеш споживати їжу з володарем, то ретельно спостерігай, що перед тобою,","і постав перешкоду в гортані твоїй, якщо ти жадібний.","Не захоплюйся ласими стравами його; це — оманна їжа.","Не піклуйся про те, щоб нажити багатство; залиш такі думки твої.","Спрямуєш очі твої на нього, і — його вже немає; тому що воно зробить собі крила і, як орел, полетить до неба.","Не споживай їжі у людини заздрісної і не захоплюйся ласими стравами її;","тому що, які думки у душі її, така й вона; «їж і пий», говорить вона тобі, а серце її не з тобою.","Шматок, який ти з’їв, виблюєш, і добрі слова твої ти витратиш даремно.","У вуха нерозумного не говори, тому що він знехтує розумні слова твої.","Не пересувай межі давньої і на поля сиріт не заходь,","тому що Захисник їх сильний; Він вступиться у справу їх з тобою.","Прихили серце твоє до навчання і вуха твої — до розумних слів.","Не залишай юнака без покарання: якщо покараєш його різкою, він не помре;","ти покараєш його різкою і спасеш душу його від пекла.","Сину мій! якщо серце твоє буде мудре, то порадіє і моє серце;","і нутрощі мої будуть радіти, коли вуста твої будуть говорити справедливе.","Нехай не заздрить серце твоє грішникам, але нехай перебуває воно в усі дні у страху Господньому;","тому що є майбутнє, і надія твоя не втрачена.","Слухай, сину мій, і будь мудрий, і направляй серце твоє на пряму путь.","Не будь між тими, хто упивається вином, між тими, хто пересичується м’ясом:","тому що п’яниця і той, хто пересичується, зубожіють, і сонливість одягне в руб’я.","Слухайся батька твого: він породив тебе; і не зневажай матері твоєї, коли вона і постаріє.","Купи істину і не продавай мудрости і вчення і розуму.","Торжествує батько праведника, і хто породив мудрого, радіє за нього.","Нехай веселиться батько твій і нехай торжествує мати твоя, що народила тебе.","Сину мій! віддай серце твоє мені, і очі твої нехай спостерігають за путями моїми,","тому що блудниця — глибока прірва, і чужа дружина — вузький колодязь;","вона, як розбійник, сидить у засідці і множить між людьми законопорушників.","У кого виття? у кого стогін? у кого сварки? у кого горе? у кого рани без причини? у кого багряні очі?","У тих, які довго сидять за вином, які приходять шукати вина приправленого.","Не дивися на вино, як воно червоніє, як воно іскриться в чаші, як воно світиться рівно:","згодом, як змій, воно вкусить, і вжалить, як аспид;","очі твої будуть дивитися на чужих дружин, і серце твоє заговорить про розпусне,","і ти будеш, як той, що спить серед моря, і як той, що спить на верхівці щогли.","[І скажеш:] «били мене, мені не було боляче; штовхали мене, я не відчував. Коли прокинуся, знову буду шукати того самого»."],"x":{"1":"30.31.13","4":"71.6.6:9","6":"30.14.10","9":"26.9.8","10":"26.22.28","11":"26.22.23","13":"26.13.25","15":"26.27.11","17":"25.36.1|26.24.1","20":"62.13.13|66.5.18","21":"26.21.17","22":"26.1.8","24":"26.10.1|26.15.20","26":"50.15.19|51.7.6","27":"30.19.2","30":"31.5.11","33":"66.5.18|58.2.16","35":"31.56.12"}},{"v":["Не ревнуй злим людям і не бажай бути з ними,","тому що про насильство помишляє серце їх, і про зле говорять вуста їхні.","Мудрістю влаштовується дім і розумом утверджується,","і з умінням наповнюється він усередині всяким дорогоцінним і прекрасним майном.","Людина мудра сильна, і людина розумна зміцнює силу свою.","Тому обдумано веди війну твою, і успіх буде при багатьох нарадах.","Для нерозумного занадто високою є мудрість; біля воріт не відкриє він уст своїх.","Хто замишляє зробити зло, того називають зловмисником.","Помисел глупоти — гріх, і кощунник — мерзота для людей.","Якщо ти в день нещастя виявився слабким, то бідна сила твоя.","Рятуй узятих на смерть, і невже відмовишся від приречених на убиття?","Чи скажеш: «ось, ми не знали цього»? А Той, Хто випробовує серця, хіба не знає? Той, Хто спостерігає за душею твоєю, знає це, і воздасть людині за ділами її.","Їж, сину мій, мед, тому що він приємний, і стільник, який солодкий для гортані твоєї:","таке і пізнання мудрости для душі твоєї. Якщо ти знайшов її, тобто майбутнє, і надія твоя не втрачена.","Не замислюй зла, нечестивий, проти житла праведника, не спустошуй місця спокою його,","бо сім разів упаде праведник, і встане; а нечестиві впадуть у погибель.","Не радій, коли упаде ворог твій, і нехай не веселиться серце твоє, коли він спіткнеться.","Інакше, побачить Господь, і неугодне буде це в очах Його, і Він відверне від нього гнів Свій.","Не обурюйся на злодіїв і не заздри нечестивим,","тому що злий не має майбуття, — світильник нечестивих погасне.","Бійся, сину мій, Господа і царя; із заколотниками не спілкуйся,","тому що несподівано прийде погибель від них, і біду від них обох хто передбачить?","Сказано також мудрими: мати упередженість на суді — недобре.","Хто говорить винному: «ти правий», того будуть проклинати народи, того будуть ненавидіти племена;","а викривачів будуть любити, і на них прийде благословення.","В уста цілує той, хто відповідає словами вірними.","Зверши справи твої поза домом, закінчи їх на полі твоєму, і потім облаштовуй і дім твій.","Не будь лжесвідком на ближнього твого: для чого тобі обманювати вустами твоїми?","Не говори: «як він вчинив зі мною, так і я зроблю з ним, воздам людині за ділами її».","Проходив я мимо поля чоловіка лінивого і мимо виноградника чоловіка бідного на розум:","і ось, усе це заросло терням, поверхня його вкрилася кропивою, і кам’яна огорожа його зруйнувалася.","І подивився я, і взяв до серця свого, і подивився й отримав урок:","«трохи поспиш, трохи подрімаєш, трохи, склавши руки, полежиш, —","і прийде, як перехожий, бідність твоя, і нестаток твій — як людина озброєна»."],"x":{"1":"25.36.1|26.23.17","2":"25.9.28","6":"26.20.18","7":"26.14.6","11":"25.81.4","12":"24.34.11|25.61.13|32.32.19|62.2.6|76.22.12","15":"26.1.11","16":"25.36.24|40.5.2","17":"24.31.29","19":"25.36.1","20":"26.13.9","21":"50.22.21|56.2.17|62.13.2","23":"26.18.5","24":"31.5.23","29":"26.17.13","31":"26.15.19","33":"26.6.10","34":"26.28.19"}},{"v":["І це притчі Соломона, які зібрали люди Єзекії, царя Юдейського.","Слава Божа — покривати таємницею справу, а слава царів — досліджувати справу.","Як небо у висоті й земля в глибині, так серце царів — недослідиме.","Відокреми домішки від срібла, і вийде у срібника сосуд:","віддали неправедного від царя, і престіл його утвердиться правдою.","Не величайся перед лицем царя, і на місці великих не ставай;","тому що краще, коли скажуть тобі: «йди сюди вище», ніж коли понизять тебе перед знатним, якого бачили очі твої.","Не вступай поспішно в тяжбу: інакше що будеш робити після закінчення, коли суперник твій осоромить тебе?","Веди тяжбу із суперником твоїм, але таємниці іншого не відкривай,","щоб не докорив тобі той, хто почує це, і тоді нечестя твоє не відійде від тебе. [Любов і дружба звільняють: збережи їх для себе, щоб не зробитися тобі достойним ганьби; збережи путі твої благовпорядкованими.]","Золоті яблука у срібних прозорих посудинах — слово, сказане пристойно.","Золота серга і прикраса з чистого золота — мудрий викривач для уважного вуха.","Що прохолода від снігу під час жнив, те вірний посланець для того, хто посилає його: він доставляє душі господаря свого відраду.","Що хмари і вітри без дощу, те людина, яка хвалиться подарунками, яких не дає.","Лагідністю схиляється до милости вельможа, і м’який язик переломлює кістки.","Знайшов ти мед, — їж, скільки тобі потрібно, щоб не пересититися ним і не виблювати його.","Не вчащай входити в дім друга твого, щоб ти не надокучив йому і він не зненавидів тебе.","Що молот і меч і гостра стріла, те людина, яка виголошує лжесвідчення проти ближнього свого.","Що зламаний зуб і розслаблена нога, те надія на ненадійну [людину] в день біди.","Що холодний день, для того, хто знімає із себе одяг, що оцет на рану, те той, хто співає пісень сумному серцю. [Як міль одягу і черва дереву, так печаль шкодить серцю людини.]","Якщо голодний ворог твій, нагодуй його хлібом; і якщо він спраглий, напої його водою:","тому що, [роблячи це,] ти збираєш палаюче вугілля на голову його, і Господь воздасть тобі.","Північний вітер приносить дощ, а таємна мова — незадоволені обличчя.","Краще жити в кутку на покрівлі, ніж із сварливою дружиною у просторому домі.","Що холодна вода для виснаженої спрагою душі, те добра звістка з далекої країни.","Що збурене джерело й пошкоджена криниця, те праведник, що падає перед нечестивим.","Як недобре їсти багато меду, так домагатися слави не є слава.","Що місто зруйноване, без стін, те людина, що не володіє духом своїм."],"x":{"2":"4.29.29|62.11.33","3":"26.20.5","5":"26.20.8","7":"52.14.9-10","9":"30.19.10","14":"55.2.16","15":"26.15.1","16":"26.24.13","18":"25.58.8","22":"62.12.20|8.24.20","24":"26.21.9","25":"26.15.30","27":"26.25.16|30.3.21|62.12.3"}},{"v":["Як сніг улітку і дощ під час жнив, так честь непристойна нерозумному.","Як горобець спурхне, як ластівка полетить, так незаслужене прокляття не збудеться.","Бич для коня, вузда для осла, а палка для дурних.","Не відповідай нерозумному за глупотою його, щоб і тобі не зробитися подібним до нього;","не відповідай нерозумному за глупотою його, щоб він не став мудрецем в очах своїх.","Підрізує собі ноги, терпить неприємність той, хто дає словесне доручення дурневі.","Нерівно піднімаються ноги у кульгавого, — і притча у вустах дурнів.","Що той, хто вкладає коштовний камінь у пращу, те саме той, що віддає нерозумному шану.","Що колючий терен у руці п’яного, те притча в устах дурнів.","Сильний робить усе довільно: і нерозумного нагороджує, і всякого перехожого нагороджує.","Як пес повертається на блювотину свою, так нерозумний повторює дурість свою.","Чи бачив ти чоловіка, мудрого в очах своїх? На нерозумного більше надії, ніж на нього.","Лінивець говорить: «лев на дорозі! лев на площах!»","Двері качаються на гаках своїх, а лінивець на постелі своїй.","Лінивець опускає руку свою в чашу, і йому важко донести її до рота свого.","Лінивець в очах своїх мудріший за сімох, які відповідають обдумано.","Хапає пса за вуха, хто, проходячи мимо, втручається в чужу сварку.","Як той, хто прикидається несповна розуму, кидає вогонь, стріли і смерть,","так — чоловік, який підступно шкодить другові своєму і потім говорить: «я тільки пожартував».","Де немає більше дров, вогонь погасає, і де немає навушника, розбрат вщухає.","Вугілля — для жару і дрова — для вогню, а людина сварлива — для розпалення сварки.","Слова навушника — як ласощі, і вони входять у нутрощі утроби.","Що нечистим сріблом обкладена глиняна посудина, те полум’яні вуста і серце злісне.","Вустами своїми прикидається ворог, а у серці своєму замишляє підступи.","Якщо він говорить і ніжним голосом, не вір йому, тому що сім мерзот у серці його.","Якщо ненависть прикривається наодинці, то відкриється злоба його в народному зібранні.","Хто риє яму, той упаде в неї, і хто покотить нагору камінь, до того він повернеться.","Неправдивий язик ненавидить уражених ним, і улесливі вуста готують падіння."],"x":{"3":"25.31.9-10","4":"50.21.27","11":"57.2.22","12":"31.5.21|62.12.16","13":"26.22.13","15":"26.19.24","16":"52.19.21","21":"30.28.11:13","22":"25.54.22","24":"54.16.17|30.27.28"}},{"v":["Не хвалися завтрашнім днем, тому що не знаєш, що народить той день.","Нехай хвалить тебе інший, а не вуста твої, — чужий, а не язик твій.","Важкий камінь, вагомий і пісок; але гнів дурня важчий за них обох.","Жорстокий гнів, неприборкна лють; але хто устоїть проти ревнощів?","Краще відкрите викривання, ніж прихована любов.","Щирі докори від того, хто любить, і неправдиві поцілунки ненависника.","Сита душа зневажає і стільник, а голодній душі все гірке солодке.","Як птах, який залишив гніздо своє, так людина, яка залишила місце своє.","Масті і пахощі радують серце; так солодкий усякому друг сердечною порадою своєю.","Не залишай друга твого і друга батька твого, і в дім брата твого не ходи в день нещастя твого: краще сусід поблизу, ніж брат далеко.","Будь мудрий, сину мій, і радуй серце моє; і я буду мати, що відповідати тому, хто лихословить мене.","Розсудливий бачить біду і ховається; а недосвідчені йдуть уперед і караються.","Візьми у нього одяг його, тому що він ручився за чужого, і за стороннього візьми від нього заставу.","Хто голосно хвалить друга свого з раннього ранку, того вважатимуть за лихомовця.","Безперестанний капіж у дощовий день і сварлива дружина — рівні:","хто хоче приховати її, той хоче приховати вітер і масть у правій руці своїй, що дає знати про себе.","Як залізо гострить залізо, так людина гострить погляд друга свого.","Хто стереже смоковницю, той буде їсти плоди її; і хто береже господаря свого, той буде в шані.","Як у воді лице — до лиця, так серце людини — до людини.","Пекло й Аваддон — ненаситні; так ненаситні й очі людські. [Мерзота перед Господом той, хто зухвало піднімає очі, і нерозумні нестримані на язик.]","Що плавильня — для срібла, горно — для золота, те для людини вуста, які хвалять її. [Серце беззаконника шукає зла, серце ж праведне шукає знання.]","Товчи нерозумного, як зерно у ступі, не відокремиться від нього глупота його.","Добре спостерігай за худобою твоєю, май піклування про стада;","тому що багатство не навіки, та й влада хіба з роду в рід?","Проростає трава, і з’являється зелень, і збирають гірські трави.","Вівці — на одяг тобі, і козли — на купівлю поля.","І достатньо козячого молока на їжу тобі, на їжу домашнім твоїм і на споживу служницям твоїм."],"x":{"1":"55.4.13-14","2":"64.10.12","3":"30.22.15-16","4":"55.1.20","5":"26.28.23","6":"25.140.5","10":"26.18.20","11":"26.23.15","12":"26.22.3","13":"26.20.16","15":"30.25.24","17":"75.10.24","20":"30.14.9","21":"26.17.3","22":"51.3.4","24":"71.6.7"}},{"v":["Нечестивий біжить, коли ніхто не женеться за ним; а праведник сміливий, як лев.","Коли країна відступить від закону, тоді багато в ній начальників; а при розумному і знаючому мужі вона довговічна.","Чоловік бідний і який гнобить слабких, те саме, що злива, яка змиває хліб.","Відступники від закону хвалять нечестивих, а ті, що зберігають закон, обурюються на них.","Злі люди не розуміють справедливости, а ті, що шукають Господа, розуміють усе.","Краще бідний, який ходить у своїй непорочності, ніж той, хто спотворює шляхи свої, хоч він і багатий.","Той, хто зберігає закон, — син розумний, а той, хто спілкується з марнотратцями, осоромлює батька свого.","Хто примножує майно своє ростом і лихвою, збере його для благодійника бідних.","Хто відхиляє вухо своє від слухання закону, того і молитва — мерзота.","Хто спокушає праведних на путь зла, сам упаде в свою яму, а непорочні успадковують добро.","Чоловік багатий — мудрець в очах своїх, але розумний бідняк викриє його.","Коли торжествують праведники, велика слава, але коли підіймаються нечестиві, люди ховаються.","Хто приховує свої злочини, той не буде мати успіху; а хто зізнається і залишає їх, той буде помилуваний.","Блаженна людина, яка завжди перебуває у благоговінні; а хто озлоблює серце своє, той потрапить у біду.","Як рикаючий лев і голодний ведмідь, так нечестивий володар над бідним народом.","Нерозумний правитель багато робить утисків, а хто ненавидить користь, продовжить дні.","Чоловік, винний у пролитті людської крови, буде бігати до могили, щоб хто не схопив його.","Хто ходить непорочно, той буде неушкодженим; а хто ходить кривими путями, упаде на одній з них.","Хто обробляє землю свою, той буде насичуватися хлібом, а хто наслідує бездіяльних, той насититься убогістю.","Вірна людина багата благословеннями, а хто поспішає розбагатіти, той не залишиться непокараним.","Бути упередженим — недобре: така людина і за шматок хліба вчинить неправду.","Поспішає до багатства заздрісна людина, і не думає, що убогість осягне її.","Хто викриває людину, знайде потім більшу приязнь, ніж той, хто лестить язиком.","Хто обкрадає батька свого і матір свою і говорить: «це не гріх», той — спільник грабіжникам.","Пихатий розпалює сварку, а хто уповає на Господа, буде благоденствувати.","Хто сподівається на себе, той нерозумний; а хто ходить в мудрості, той буде цілий.","Хто дає убогому, не зубожіє; а хто закриває очі свої від нього, на тому багато проклять.","Коли підносяться нечестиві, люди ховаються, а коли вони падають, примножуються праведники."],"x":{"1":"2.26.36|4.28.25","2":"26.29.8","4":"31.5.20","5":"30.21.7","6":"26.19.1","7":"26.29.3","8":"24.27.16-17","9":"24.27.8-9","10":"26.26.27","12":"26.29.2","13":"25.31.5|58.1.9","14":"24.3.25|62.11.20","19":"26.12.11|30.20.28","20":"26.20.21","21":"26.18.5|26.24.23","22":"71.6.9","24":"50.15.5","25":"26.13.10","27":"4.15.7|64.9.9"}},{"v":["Людина, яка, будучи викритою, озлоблює шию свою, раптово скрушиться, і не буде їй зцілення.","Коли примножуються праведники, веселиться народ, а коли панує нечестивий, народ стогне.","Чоловік, який любить мудрість, радує батька свого; а хто знається з блудницями, той марнує майно.","Цар правосуддям утверджує землю, а хто любить подарунки, розоряє її.","Чоловік, який лестить другові своєму, розстелює сіті ногам його.","У гріху злої людини — тенета для неї, а праведник веселиться і радіє.","Праведник ретельно вникає у позов бідних, а нечестивий не розглядає справи.","Люди розпусні обурюють місто, а мудрі втихомирюють заколот.","Розумна людина, маючи суд з людиною дурною, чи сердиться, чи сміється, — не має спокою.","Кровожерливі люди ненавидять непорочного, а праведні піклуються про його життя.","Нерозумний весь гнів свій виливає, а мудрий стримує його.","Якщо правитель слухає неправдиві слова, то і всі службовці у нього нечестиві.","Бідний і лихвар зустрічаються один з одним; але світло очам того й іншого дає Господь.","Якщо цар судить бідних за правдою, то престіл його назавжди утвердиться.","Різка і викриття дають мудрість; але отрок, залишений у нехтуванні, чинить сором своїй матері.","При примноженні нечестивих збільшується беззаконня; але праведники побачать падіння їх.","Карай сина твого, і він дасть тобі спокій, і принесе радість душі твоїй.","Без одкровення з висоти народ неприборканий, а хто дотримується закону — блаженний.","Словами не навчиться раб, тому що, хоча він розуміє їх, але не слухається.","Чи бачив ти чоловіка необачного у словах своїх? на нерозумного більше надії, ніж на нього.","Якщо з дитинства виховувати раба у розкоші, то згодом він захоче бути сином.","Чоловік гнівливий заводить сварку, і запальний багато грішить.","Гордість людини принижує її, а смиренний духом здобуває шану.","Хто ділиться зі злодієм, той ненавидить душу свою; чує він прокляття, але не оголошує про те.","Острах перед людьми ставить тенета; а хто уповає на Господа, буде у безпеці.","Багато хто шукає прихильного лиця правителя, але доля людини — від Господа.","Мерзота для праведників — людина неправедна, і мерзота для нечестивого — хто йде прямим шляхом."],"x":{"1":"26.28.14","2":"1.2.23","3":"26.10.1|52.15.13","6":"25.9.17","7":"26.28.5","8":"26.11.11|27.9.18","11":"26.15.1-2","12":"30.10.2","14":"26.16.12|26.20.28|26.25.5","15":"26.10.1","16":"25.36.36","17":"26.23.13","20":"27.5.1|55.1.19|26.26.12","21":"30.33.26","22":"26.15.18","23":"24.22.29|26.15.33|50.23.12","24":"2.5.1","25":"50.14.5|26.16.20|32.17.7","26":"26.19.6","27":"53.15.19"}},{"v":["Слова Агура, сина Іакеєвого. Натхненні слова, які сказав цей чоловік Іфиїлу, Іфиїлу й Укалу:","справді, я більший невіглас, ніж будь-хто з людей, і розуму людського немає у мене,","і не навчився я мудрости, і пізнання святих не маю.","Хто піднімався на небо і сходив? хто зібрав вітер у пригорщі свої? хто зав’язав воду в одяг? хто поставив усі межі землі? яке ім’я йому? і яке ім’я синові його? чи знаєш?","Усяке слово Бога чисте; Він — щит тим, хто уповає на Нього.","Не додавай до слів Його, щоб Він не викрив тебе, і ти не виявився неправдомовцем.","Дві речі я прошу в Тебе, не відмов мені, перше ніж я помру:","суєту і неправду віддали від мене, убогости і багатства не давай мені, годуй мене насущним хлібом,","щоб, переситившись, я не зрікся Тебе і не сказав: «хто Господь?» і щоб, зубожівши, не став красти і вживати ім’я Бога мого марно.","Не лихослов раба перед господарем його, щоб він не прокляв тебе, і ти не залишився винним.","Є рід, який проклинає батька свого і не благословляє матері своєї.","Є рід, який чистий в очах своїх, тоді як не омитий від нечистот своїх.","Є рід — о, які зарозумілі очі його, і як підняті вії його!","Є рід, у якого зуби — мечі, і щелепи — ножі, щоб пожирати бідних на землі й убогих між людьми.","У ненаситності дві дочки: «давай, давай!» Ось три невситимих, і чотири, які не скажуть: «достатньо!»","Пекло й утроба безплідна, земля, що не насичується водою, і вогонь, що не говорить: «досить!»","Око, що насміхається з батька і нехтує покірністю до матері, виклюють ворони дольні, і пожеруть пташенята орлині!","Три речі незбагненні для мене, і чотирьох я не розумію:","путі орла на небі, путі змія на скелі, путі корабля серед моря і путі чоловіка до дівчини.","Така путь і дружини перелюбної; поїла й обтерла рот свій, і говорить: «я нічого поганого не зробила».","Від трьох трясеться земля, чотирьох вона не може носити:","раба, коли він стає царем; нерозумного, коли він досита їсть хліб;","ганебну жінку, коли вона виходить заміж, і служницю, коли вона займає місце пані своєї.","Ось чотири малих на землі, але вони мудріші за мудрих:","мурахи — народ несильний, але влітку заготовляють їжу свою;","гірські миші — народ слабкий, але ставлять доми свої на скелі;","у сарани немає царя, але виступає уся вона струнко;","павук лапками чіпляється, але буває у царських чертогах.","Ось троє мають струнку ходу, і четверо струнко виступають:","лев, силач між звірами, не посторониться ні перед ким;","кінь і козел, [проводир стада,] і цар серед народу свого.","Якщо ти у зарозумілості своїй зробив дурість і помислив зле, то поклади руку на вуста;","тому що, як збивання молока робить масло, поштовх у ніс викликає кров, так і пробудження гніву чинить сварку."],"x":{"2":"63.15.9|55.1.10","4":"24.38.4-5","5":"25.11.7","6":"4.4.2|4.12.32","8":"75.13.5|50.6.11|71.6.8","9":"4.8.12-14","12":"31.65.5","13":"26.6.17","14":"25.54.22|26.12.18|32.9.8","17":"26.20.20","25":"26.6.6","30":"37.7.4|76.5.5","31":"27.8.4","33":"26.15.18"}},{"v":["Слова Лемуїла царя. Наставляння, які дала йому мати його:","що, сину мій? що, сину утроби моєї? що, сину обітниць моїх?","Не віддавай жінкам сил твоїх, ні шляхів твоїх згубницям царів.","Не царям, Лемуїле, не царям пити вино, і не князям — сикеру,","щоб, напившись, вони не забули закону і не викривили суду всіх пригноблених.","Дайте сикеру тому, хто гине, і вино засмученому душею;","нехай він вип’є і забуде бідність свою і не згадає більше про своє страждання.","Відкривай уста твої за безмовного і для захисту всіх сиріт.","Відкривай уста твої для правосуддя і для справи бідного й убогого.","Хто знайде доброчесну дружину? ціна її вища за перли;","упевнене у ній серце чоловіка її, і він не залишиться без прибутку;","вона відплачує йому добром, а не злом, в усі дні життя свого.","Добуває вовну і льон, і з охотою працює своїми руками.","Вона, як купецькі кораблі, здалеку добуває хліб свій.","Вона встає ще вночі і роздає їжу в домі своєму і визначає денну працю служницям своїм.","Задумає вона про поле, і придбає його; від плодів рук своїх насаджує виноградник.","Підперезує силою стегна свої і зміцнює м’язи свої.","Вона відчуває, що заняття її добре, і — світильник її не гасне і вночі.","Простягає руки свої до прядки, і персти її беруться за веретено.","Долоню свою вона відкриває бідному, і руку свою подає нужденному.","Не боїться холоду для родини своєї, тому що вся родина її одягнена у подвійний одяг.","Вона робить собі килими; висон і пурпур — одяг її.","Чоловік її відомий біля воріт, коли сидить зі старійшинами землі.","Вона робить покривала і продає, і пояси доставляє купцям фінікійським.","Сила і краса — одяг її, і весело дивиться вона на майбутнє.","Вуста свої відкриває з мудрістю, і лагідне наставляння на язиці її.","Вона спостерігає за господарством у домі своєму і не їсть хліба неробства.","Встають діти й ублажають її, — чоловік, і хвалить її:","«багато було дружин доброчесних, але ти перевершила всіх їх».","Миловидість оманлива і краса суєтна; але дружина, яка боїться Господа, гідна похвали.","Дайте їй від плоду рук її, і нехай прославлять її біля воріт діла її!"],"x":{"3":"4.17.17","5":"20.3.15|31.5.22","6":"17.8.10","8":"26.24.11","9":"2.19.15|4.1.16","10":"26.12.4|26.18.23","11":"26.14.1","12":"30.26.2","21":"27.10.18","23":"30.40.19","25":"56.3.4","26":"73.2.3","30":"26.11.22","31":"51.14.9"}}];
